WITH lines AS (SELECT id, service, host, level, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, attr_value) SELECT *, SUM(status_code) OVER (PARTITION BY service ORDER BY status_code, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_status_code, SUM(status_code) OVER (PARTITION BY host ORDER BY status_code, id, attr_key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_status_code, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY status_code DESC, id, attr_key) AS seq_no FROM lines;
